// Pin Definitions
#define FSRSQUARE_PIN_1	A3
#define RGBLED_PIN_B	5
#define RGBLED_PIN_G	6
#define RGBLED_PIN_R	9



// Global variables and defines
#define rgbLed_TYPE COMMON_ANODE
// object initialization
FSR fsrSquare(FSRSQUARE_PIN_1);
RGBLed rgbLed(RGBLED_PIN_R,RGBLED_PIN_G,RGBLED_PIN_B,rgbLed_TYPE);


// define vars for testing menu
const int timeout = 10000;       //define timeout of 10 sec
char menuOption = 0;
long time0;

// Setup the essentials for your circuit to work. It runs first every time your circuit is powered with electricity.
void setup() 
{
    // Setup Serial which is useful for debugging
    // Use the Serial Monitor to view printed messages
    Serial.begin(9600);
    while (!Serial) ; // wait for serial port to connect. Needed for native USB
    Serial.println("start");

    rgbLed.turnOff();              // Start with  LED Strip RGB turned off
    menuOption = menu();

}

// Main logic of your circuit. It defines the interaction between the components you selected. After setup, it runs over and over again, in an eternal loop.
void loop() 
{


    if(menuOption == '1') {
    // Force Sensitive Resistor - Square - Test Code
    // Read FSR resistance value. try also fsrSquare.getResistance()
    // For more information see Sparkfun website - www.sparkfun.com/products/9375
    // Note, the default Vcc and external resistor values for FSR calculations are 5V ang 3300Okm, if you are not 
    //       using these default valuse in your circuit go to FSR.cpp and change default values in FSR constructor
    float fsrSquareForce = fsrSquare.getForce();
    Serial.print(F("Force: ")); Serial.print(fsrSquareForce); Serial.println(F(" [g]"));

    }
    else if(menuOption == '2') {
    // RGB LED Clear Common Anode - Test Code
    // The RGB LED will turn PURPLE for 500ms(half a second) and turn off
    rgbLed.setRGB(160, 3, 255);    // 1. sets RGB LED color to purple. Change the values in the brackets to (255,0,0) for pure RED, (0,255,0) for pure GREEN and (0,0,255) for pure BLUE.
    delay(500);                         // 2. change the value in the brackets (500) for a longer or shorter delay in milliseconds.
    rgbLed.setRGB(0, 0, 0);        // 3. turns RGB LED off (showing no color). Change the values in the brackets to alter the color.
    delay(500);                         // 4. change the value in the brackets (500) for a longer or shorter delay in milliseconds.  
    }

    if (millis() - time0 > timeout)
    {
        menuOption = menu();
    }

}



// Menu function for selecting the components to be tested
// Follow serial monitor for instrcutions
char menu()
{

    Serial.println(F("\nWhich component would you like to test?"));
    Serial.println(F("(1) Force Sensitive Resistor - Square"));
    Serial.println(F("(2) RGB LED Clear Common Anode"));
    Serial.println(F("(menu) send anything else or press on board reset button\n"));
    while (!Serial.available());

    // Read data from serial monitor if received
    while (Serial.available()) 
    {
        char c = Serial.read();
        if (isAlphaNumeric(c)) 
        {   

            if(c == '1') 
    			Serial.println(F("Now Testing Force Sensitive Resistor - Square"));
    		else if(c == '2') 
    			Serial.println(F("Now Testing RGB LED Clear Common Anode"));
            else
            {
                Serial.println(F("illegal input!"));
                return 0;
            }
            time0 = millis();
            return c;
        }
    }
}

